{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "padding": 16
      },
      "children": [
        "title_h1",
        "intro_text",
        "top_laptops_h2",
        "asus_card",
        "lenovo_card",
        "acer_card",
        "quick_actions_h2",
        "quick_actions_stack",
        "sources_h2",
        "sources_stack"
      ]
    },
    "title_h1": {
      "type": "Text",
      "props": {
        "text": "Laptop Recommendations for Graphic Design Students",
        "variant": "h1"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "Selecting the right laptop is crucial for graphic design students, balancing performance for demanding software with display quality for accurate visual work. The following recommendations meet your requirements for at least 16GB RAM, a dedicated GPU, a 15-inch or larger display with good color accuracy, all within a $1500-$2000 USD budget.",
        "variant": "body"
      },
      "children": []
    },
    "top_laptops_h2": {
      "type": "Text",
      "props": {
        "text": "Top Laptops for Creative Studies",
        "variant": "h2"
      },
      "children": []
    },
    "asus_card": {
      "type": "Card",
      "props": {},
      "children": [
        "asus_header_stack",
        "asus_summary_label",
        "asus_summary_text",
        "asus_advantage_label",
        "asus_advantage_text",
        "asus_button"
      ]
    },
    "asus_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "asus_icon",
        "asus_title_h3"
      ]
    },
    "asus_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000289_01_3_laptop.svg"
      },
      "children": []
    },
    "asus_title_h3": {
      "type": "Text",
      "props": {
        "text": "ASUS ROG Strix G16 (2023/2024)",
        "variant": "h3"
      },
      "children": []
    },
    "asus_summary_label": {
      "type": "Text",
      "props": {
        "text": "Summary:",
        "variant": "label"
      },
      "children": []
    },
    "asus_summary_text": {
      "type": "Text",
      "props": {
        "text": "A powerful laptop with a high-refresh-rate display and robust cooling, suitable for intensive graphic design tasks.",
        "variant": "body"
      },
      "children": []
    },
    "asus_advantage_label": {
      "type": "Text",
      "props": {
        "text": "Key Advantage:",
        "variant": "label"
      },
      "children": []
    },
    "asus_advantage_text": {
      "type": "Text",
      "props": {
        "text": "Features a 16-inch QHD+ (2560x1600) display with excellent color coverage (often 100% DCI-P3) and high performance NVIDIA RTX 40-series graphics (e.g., RTX 4060), ensuring smooth operation for design software and rendering.",
        "variant": "body"
      },
      "children": []
    },
    "asus_button": {
      "type": "Button",
      "props": {
        "label": "View ASUS Strix G16"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.asus.com/us/laptops/for-gaming/rog-strix/rog-strix-g16/"
          }
        }
      }
    },
    "lenovo_card": {
      "type": "Card",
      "props": {},
      "children": [
        "lenovo_header_stack",
        "lenovo_summary_label",
        "lenovo_summary_text",
        "lenovo_advantage_label",
        "lenovo_advantage_text",
        "lenovo_button"
      ]
    },
    "lenovo_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "lenovo_icon",
        "lenovo_title_h3"
      ]
    },
    "lenovo_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000289_01_3_laptop.svg"
      },
      "children": []
    },
    "lenovo_title_h3": {
      "type": "Text",
      "props": {
        "text": "Lenovo Legion Slim 5 16 (2023)",
        "variant": "h3"
      },
      "children": []
    },
    "lenovo_summary_label": {
      "type": "Text",
      "props": {
        "text": "Summary:",
        "variant": "label"
      },
      "children": []
    },
    "lenovo_summary_text": {
      "type": "Text",
      "props": {
        "text": "Offers a strong balance of performance, a high-quality display, and a more understated design than typical gaming laptops.",
        "variant": "body"
      },
      "children": []
    },
    "lenovo_advantage_label": {
      "type": "Text",
      "props": {
        "text": "Key Advantage:",
        "variant": "label"
      },
      "children": []
    },
    "lenovo_advantage_text": {
      "type": "Text",
      "props": {
        "text": "Equipped with a 16-inch WQXGA (2560x1600) IPS display, known for its color accuracy and brightness, paired with NVIDIA RTX 40-series GPUs (e.g., RTX 4060). It also boasts a comfortable keyboard and efficient cooling.",
        "variant": "body"
      },
      "children": []
    },
    "lenovo_button": {
      "type": "Button",
      "props": {
        "label": "View Lenovo Legion Slim 5"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.lenovo.com/us/en/p/laptops/legion-laptops/legion-slim-series/lenovo-legion-slim-5-gen-8-(16-inch-amd)/82y9000nus"
          }
        }
      }
    },
    "acer_card": {
      "type": "Card",
      "props": {},
      "children": [
        "acer_header_stack",
        "acer_summary_label",
        "acer_summary_text",
        "acer_advantage_label",
        "acer_advantage_text",
        "acer_button"
      ]
    },
    "acer_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "acer_icon",
        "acer_title_h3"
      ]
    },
    "acer_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000289_01_3_laptop.svg"
      },
      "children": []
    },
    "acer_title_h3": {
      "type": "Text",
      "props": {
        "text": "Acer Swift X 16 (2023)",
        "variant": "h3"
      },
      "children": []
    },
    "acer_summary_label": {
      "type": "Text",
      "props": {
        "text": "Summary:",
        "variant": "label"
      },
      "children": []
    },
    "acer_summary_text": {
      "type": "Text",
      "props": {
        "text": "A more portable and creator-focused option featuring a stunning OLED display, ideal for color-critical work.",
        "variant": "body"
      },
      "children": []
    },
    "acer_advantage_label": {
      "type": "Text",
      "props": {
        "text": "Key Advantage:",
        "variant": "label"
      },
      "children": []
    },
    "acer_advantage_text": {
      "type": "Text",
      "props": {
        "text": "Its standout feature is the 16-inch 2.5K (2560x1600) OLED display, offering exceptional contrast, true blacks, and 100% DCI-P3 color gamut coverage, which is perfect for graphic design. It includes NVIDIA RTX 4050 or 4060 graphics within a relatively slim chassis.",
        "variant": "body"
      },
      "children": []
    },
    "acer_button": {
      "type": "Button",
      "props": {
        "label": "View Acer Swift X 16"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.acer.com/us-en/laptops/swift/swift-x/pdp/NX.KE8AA.001"
          }
        }
      }
    },
    "quick_actions_h2": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "quick_actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "bestbuy_button",
        "adobe_button"
      ]
    },
    "bestbuy_button": {
      "type": "Button",
      "props": {
        "label": "Compare Laptops on BestBuy"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.bestbuy.com/site/laptop-computers/all-laptops/pcmcat138500050001.c?id=pcmcat138500050001"
          }
        }
      }
    },
    "adobe_button": {
      "type": "Button",
      "props": {
        "label": "Adobe Creative Cloud Student Plan"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.adobe.com/creativecloud/buy/students.html"
          }
        }
      }
    },
    "sources_h2": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h2"
      },
      "children": []
    },
    "sources_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "asus_source_button",
        "lenovo_source_button",
        "acer_source_button"
      ]
    },
    "asus_source_button": {
      "type": "Button",
      "props": {
        "label": "ASUS Official Website"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.asus.com/us/"
          }
        }
      }
    },
    "lenovo_source_button": {
      "type": "Button",
      "props": {
        "label": "Lenovo Official Website"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.lenovo.com/us/en/"
          }
        }
      }
    },
    "acer_source_button": {
      "type": "Button",
      "props": {
        "label": "Acer Official Website"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.acer.com/us-en/"
          }
        }
      }
    }
  }
}
